  const slugify = value => String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  for (const route of Object.values(routes)) {
    Object.freeze(route);
    for (const key of [route.slug, ...(route.isProfile ? [route.href.slice(1, -1)] : [])]) {
      if (lookup[key] && lookup[key] !== route) throw new Error('Ambiguous tool route: ' + key);
      lookup[key] = route;
    }
  }
  function resolve(tool) {
    const key = slugify(tool && typeof tool === 'object' ? tool.name : tool);
    return lookup[key] || null;
  }
  return Object.freeze({ routes: Object.freeze(routes), resolve, slugify });
